// Generated by `dart run drift_dev make-migrations`, then adapted: keeps the
// generated schema checks and adds a data check for the v1 → v2 step.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:invest_young/core/db/app_database.dart';
import 'package:invest_young/core/domain/app_theme_mode.dart';

import 'generated/schema.dart';

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('schema migrations', () {
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      for (final toVersion in versions.skip(i + 1)) {
        test('from $fromVersion to $toVersion', () async {
          final schema = await verifier.schemaAt(fromVersion);
          final db = AppDatabase(schema.newConnection());
          await verifier.migrateAndValidate(db, toVersion);
          await db.close();
        });
      }
    }
  });

  test('v1 → v2 keeps the profile and defaults the theme to system', () async {
    final schema = await verifier.schemaAt(1);
    schema.rawDatabase.execute('''
      INSERT INTO user_profiles (age_range, employment, has_dependents,
        has_high_interest_debt, risk_score, risk_profile, knowledge_level,
        emergency_months, locale)
      VALUES ('21_25', 'student', 0, 0, 8, 'moderate', 'basic', 5, 'ca')
    ''');

    final db = AppDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 2);
    // Raw query: the generated row class has the columns of the latest schema.
    final profile = await db
        .customSelect(
          'SELECT locale, emergency_months, theme_mode FROM user_profiles',
        )
        .getSingle();
    expect(profile.read<String>('locale'), 'ca');
    expect(profile.read<int>('emergency_months'), 5);
    expect(profile.read<String>('theme_mode'), AppThemeMode.system.dbValue);
    await db.close();
  });

  test('v2 → v3 keeps the profile with the reminder off at 9:00', () async {
    final schema = await verifier.schemaAt(2);
    schema.rawDatabase.execute('''
      INSERT INTO user_profiles (age_range, employment, has_dependents,
        has_high_interest_debt, risk_score, risk_profile, knowledge_level,
        emergency_months, locale, theme_mode)
      VALUES ('21_25', 'student', 0, 0, 8, 'moderate', 'basic', 5, 'es', 'dark')
    ''');

    final db = AppDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 3);
    final profile = await db
        .customSelect(
          'SELECT theme_mode, reminder_day, reminder_minute_of_day '
          'FROM user_profiles',
        )
        .getSingle();
    expect(profile.read<String>('theme_mode'), AppThemeMode.dark.dbValue);
    expect(profile.read<int?>('reminder_day'), null);
    expect(profile.read<int>('reminder_minute_of_day'), 540);
    await db.close();
  });

  test('v3 → v4 keeps the profile with the app lock off', () async {
    final schema = await verifier.schemaAt(3);
    schema.rawDatabase.execute('''
      INSERT INTO user_profiles (age_range, employment, has_dependents,
        has_high_interest_debt, risk_score, risk_profile, knowledge_level,
        emergency_months, locale, reminder_day)
      VALUES ('21_25', 'student', 0, 0, 8, 'moderate', 'basic', 5, 'es', 10)
    ''');

    final db = AppDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 4);
    final profile = await db.select(db.userProfiles).getSingle();
    expect(profile.reminderDay, 10);
    expect(profile.appLockEnabled, false);
    await db.close();
  });
}
